UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_111');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_111'), 'The new design: access tokens live 15 minutes and are verified locally (signature and exp only); refresh tokens are opaque, hashed in auth.refresh_tokens and checked against the table on every refresh. An attacker copied both tokens of learner u_1042 right after the 14:00 refresh. Fake-clock test log:

14:00:00 refresh -> new access token (iat 14:00:00, exp 14:15:00) + new refresh token
14:05:41 POST /auth/password-reset 204
         UPDATE auth.refresh_tokens SET revoked_at = now() WHERE user_id = ''u_1042'' AND revoked_at IS NULL  -- 1 row
14:09:00 GET /me/progress (access token from 14:00) -> 200
14:10:00 POST /auth/refresh (refresh token from 14:00) -> 401 refresh_token_revoked
14:15:00 GET /me/progress (access token from 14:00) -> 401 token_expired

Statement: "The attacker can call the API with the copied access token until 14:15 at the latest, and cannot obtain a new access token after the reset."', 'single_choice'::question_type, 'True. The access token is verified without a lookup, so the reset cannot touch it: it keeps working until its exp at 14:15, as the 200 at 14:09 shows. Getting a new one requires the refresh token, and the refresh endpoint checks auth.refresh_tokens, where the reset set revoked_at on the only active row, hence the 401 at 14:10. That bounded window (at most the access token lifetime) is the whole point of the 15-minute access token plus refresh token design. The common misconception is that a password reset signs out a JWT immediately; it only stops the next refresh, so the access token lifetime is the length of the window you accept.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_111') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
