WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_111'), 'An internal admin tool uses server-side sessions. Its logout handler:

@Post("logout")
@HttpCode(204)
logout(@Res({ passthrough: true }) res: Response) {
  res.clearCookie("sid", { path: "/", secure: true, httpOnly: true });
}

Response header: Set-Cookie: sid=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; Secure

After the click on Logout:

SELECT id, user_id, expires_at FROM admin.sessions WHERE user_id = ''u_7'';
--  id      | user_id |       expires_at
-- 9f1c…e2  | u_7     | 2026-10-26 21:00:00+00

Statement: "Because the logout response cleared the sid cookie, a copy of the sid value taken before logout can no longer be used against the admin tool."', 'single_choice'::question_type, 'False. clearCookie only tells this one browser to forget its copy. The session row 9f1c…e2 is still in admin.sessions with an expiry in the future, so any request that presents the old sid value, from curl or another browser, still finds a valid session until 21:00. Logout in a server-side session design must delete or revoke the row (DELETE FROM admin.sessions WHERE id = $1) and then clear the cookie; the OWASP Session Management Cheat Sheet asks for the session to be invalidated on the server side. The misconception is that logout is something the client does: the server''s state decides whether a credential works.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_111') AND order_index = 2)
    RETURNING id
)
