UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_121');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_121'), 'Sign-in response from https://api.codedev.test (before the fix):

Set-Cookie: cd_rt=rt_K7mQ2v...; Max-Age=2592000; Domain=codedev.test; Path=/auth/refresh; Secure; HttpOnly; SameSite=Strict

Learner preview apps run learner-written server code at https://<id>.preview.codedev.test. The preview page of u-4821 contains:

<img src="https://u-4821.preview.codedev.test/auth/refresh" alt="">

Statement: "Because the cookie is HttpOnly, SameSite=Strict and limited to Path=/auth/refresh, a signed-in learner who opens this preview page does not send cd_rt to the preview app''s server."', 'single_choice'::question_type, 'False. Domain=codedev.test makes the cookie match every host under codedev.test (RFC 6265, section 5.1.3 domain-match), including u-4821.preview.codedev.test. Path only compares the request path, and the image requests exactly /auth/refresh on that host, so the path matches too. SameSite=Strict does not help: the preview page and the cookie''s host share the registrable domain codedev.test, so the request is same-site. HttpOnly only hides the cookie from JavaScript; the browser still puts it in the Cookie header, where the learner''s server code can log it. The fix is a host-only cookie (no Domain attribute), which RFC 6265 sends only to api.codedev.test. The misconception is that HttpOnly, Strict and Path together form a boundary; each one limits something different, and none of them limits the host.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_121') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_121'), 'Sign-in set:

Set-Cookie: __Secure-cd_rt=rt_9Lp...; Max-Age=2592000; Expires=Wed, 25 Nov 2026 09:00:00 GMT; Path=/auth/refresh; Secure; HttpOnly; SameSite=Strict

The logout handler calls res.clearCookie("__Secure-cd_rt", { secure: true, httpOnly: true, sameSite: "strict" }) and the response contains:

Set-Cookie: __Secure-cd_rt=; Path=/; Expires=Thu, 01 Jan 1970 00:00:00 GMT; HttpOnly; Secure; SameSite=Strict

DevTools > Application > Cookies after logout still lists __Secure-cd_rt with Path /auth/refresh and the old value.

Statement: "The refresh cookie survived logout because the clearing cookie had a different Path, so the browser treated it as a different cookie."', 'single_choice'::question_type, 'True. A browser identifies a stored cookie by its name, domain and path (RFC 6265, section 5.3, step 11): a new Set-Cookie replaces an old cookie only when all three match. The clearing header has Path=/ (the default of clearCookie when no path is passed), so it describes a different cookie that is already expired and is simply not stored, while the cookie with Path=/auth/refresh keeps its value until it expires. The fix is to clear with exactly the attributes it was set with: the same name, the same Path and the same Domain (or no Domain). The misconception is that a cookie is identified by its name alone.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_121') AND order_index = 2)
    RETURNING id
)
