-- challenge chal_coding_nas_122 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_122', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-1-2' AND is_deleted = false LIMIT 1), 'auth-cookie-headers', 'Build the auth cookie headers', 'CodeDev''s refresh cookie was set with Domain=codedev.test, so browsers sent it to every subdomain, including learner preview apps that run learner-written server code. Write buildAuthCookies(config, nowMs, accessToken, refreshToken), which returns the exact Set-Cookie values for sign-in and logout. Secure goes on every cookie unless config.environment is "local-http" (a documented dev mode for plain http://), where no cookie gets it. Validate first and return { ok: false, error } for the first failing rule, in this order: "invalid ttl" (accessTtlSeconds and refreshTtlSeconds are not both whole numbers >= 1, or refresh <= access); "invalid refresh path" (refreshPath does not match /^\/[A-Za-z0-9\/_-]+$/); "SameSite=None requires Secure"; "cookie prefix requires Secure" (a name starting with __Host- or __Secure- without Secure); "__Host- cookie must not have Domain" (a __Host- name while domain is not null); "__Host- cookie requires Path=/" (refreshName starts with __Host-); "invalid token value" (a token that does not match /^[A-Za-z0-9._-]+$/). Otherwise return { ok: true, login: [access, refresh], logout: [clearAccess, clearRefresh] }. Each value uses this attribute order joined by "; ": <name>=<value>; Max-Age=<seconds>; Expires=<date>[; Domain=<domain>]; Path=<path>[; Secure]; HttpOnly; SameSite=<value>. The access cookie uses accessName, Path=/ and config.sameSite; the refresh cookie uses refreshName, Path=refreshPath and always SameSite=Strict. Expires is new Date(nowMs + ttlSeconds * 1000).toUTCString() on the fake clock nowMs. Domain appears only when config.domain is not null. A clearing cookie has the same name, an empty value, Max-Age=0, Expires=Thu, 01 Jan 1970 00:00:00 GMT and the same Domain, Path, Secure, HttpOnly and SameSite as the cookie it clears. The test runner reads { cases: [{ config, nowMs, accessToken, refreshToken }] } as JSON and prints the array of results.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_122');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_122'), 1, 'Which single boolean decides whether Secure appears, and which validation rules depend on it? And for logout: what must a clearing cookie share with the cookie it clears for the browser to treat it as the same cookie?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_122'), 2, 'Look at three places: the validation order (return the first rule that fails; check prefixes with startsWith on both names), one header builder used for all four values (collect the parts in an array, add Domain and Secure only when they apply, then join with "; "), and the units (Max-Age is in seconds, Date and nowMs are in milliseconds; toUTCString() already prints the Expires format).'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_122'), 3, 'A similar cookie on other input: a language cookie named lang with value vi, ttl 3600 s, Path=/, SameSite=Lax, no Domain, in local-http mode at nowMs 0 gives "lang=vi; Max-Age=3600; Expires=Thu, 01 Jan 1970 01:00:00 GMT; Path=/; HttpOnly; SameSite=Lax", and its clearing value is "lang=; Max-Age=0; Expires=Thu, 01 Jan 1970 00:00:00 GMT; Path=/; HttpOnly; SameSite=Lax". Renamed __Host-lang with Domain=codedev.test in production, the same config is rejected before any header is built.');
