-- challenge chal_quiz_nas_131 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_131', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-1-3' AND is_deleted = false LIMIT 1), 'short-lived-access-tokens-quiz', 'Expiry, units and clock skew', 'Two pieces of evidence about access token expiry: the signing code behind the pentest finding, and 401 responses for learners whose phone clocks run slow.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_131');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_131');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_131'), 'Signing and verifying before the fix:

// auth/tokens.ts
signAccess(userId: string): string {
  const now = Date.now();
  return this.hs256.sign({ sub: userId, iat: Math.floor(now / 1000), exp: now + 15 * 60 * 1000,
                          iss: "https://api.codedev.test", aud: "codedev-web" });
}

// auth/jwt.guard.ts (after the signature check passed)
if (payload.exp <= Math.floor(Date.now() / 1000)) throw new UnauthorizedException("token_expired");

Decoded payload of a token issued at 2026-10-26 09:00:00 UTC:
{"sub":"u_1042","iat":1793005200,"exp":1793006100000,"iss":"https://api.codedev.test","aud":"codedev-web"}

Statement: "Tokens issued by this code pass the expiry check for tens of thousands of years, and the signature check cannot catch it, because the API itself signed the wrong exp."', 'single_choice'::question_type, 'True. exp is a NumericDate, a number of seconds since the epoch (RFC 7519, section 2), but the code wrote milliseconds: 1793006100000 read as seconds is a date around the year 58,800, so exp <= now is false for every token this code ever issued. The signature only proves the API produced these claims; it says nothing about whether the claims are sensible, and here the API produced the wrong ones. Two fixes together: issue exp in seconds (iat + 900), and make the verifier reject any token whose exp - iat is larger than the maximum lifetime you issue, so a unit mistake fails loudly instead of creating immortal tokens. The misconception is that a valid signature means valid claims.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_131') AND order_index = 1)
    RETURNING id
)
