-- challenge chal_coding_nas_132 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_132', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 1 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-1-3' AND is_deleted = false LIMIT 1), 'hs256-access-token', 'Sign and verify a short-lived access token', 'A pentest of the CodeDev API found that the hand-written access token verifier accepted a token with "alg":"none" and no signature, and tokens whose exp was written in milliseconds. Write signToken(claims, secret) and verifyToken(token, secret, options, now) for compact HS256 JWTs, using node:crypto (createHmac, timingSafeEqual) and the fake clock now, in seconds. signToken: the header is the base64url of the exact text {"alg":"HS256","typ":"JWT"}, the payload is the base64url of JSON.stringify({ sub, iat, exp, iss, aud }) in that key order, and the signature is HMAC-SHA256 with the secret over `${header}.${payload}`, as base64url (no "=" padding); the token is header.payload.signature. verifyToken checks in this order and returns { valid: false, reason } for the first failure: "malformed" (not exactly 3 parts; a part with characters outside A-Z a-z 0-9 - _ or with length % 4 === 1; a header or payload that does not decode to a JSON object, not null and not an array); "unsupported alg" (header.alg is not exactly "HS256"); "bad signature" (the signature text differs from the expected base64url text: compare their bytes with timingSafeEqual after checking the lengths); "invalid claims" (sub not a non-empty string, iat or exp not an integer, iss not a string, aud neither a string nor an array of strings, or exp <= iat); "wrong issuer" (iss !== options.issuer); "wrong audience" (a string aud other than options.audience, or an array without it); "lifetime too long" (exp - iat > options.maxLifetimeSeconds); "expired" (now >= exp + options.leewaySeconds); "not yet valid" (iat > now + options.leewaySeconds). Otherwise return { valid: true, sub }. The test runner reads { secret, options, now, sign, verify } as JSON, signs every claims object in sign, then verifies every signed token followed by every token in verify, and prints { tokens, results }.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
