INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_132'), 1, 'Which parts of a token can an attacker choose freely, and which check is the first one that proves the API wrote them? Everything you decide before that check, including which algorithm to use, must not trust the token.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_132'), 2, 'Look at: token.split(".") and a regular expression for the base64url alphabet (Buffer.from(text, "base64url") is lenient and silently skips characters it does not know, so test the text first); createHmac("sha256", secret).update(`${header}.${payload}`).digest("base64url") for the expected signature text; timingSafeEqual(Buffer.from(a), Buffer.from(b)), which throws when the lengths differ; Number.isInteger for iat and exp.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_132'), 3, 'The same rules on other input, with leewaySeconds 30 and now = 1000: exp 1000 is still valid (1000 < 1030), exp 970 is expired (1000 >= 1000); iat 1030 is valid, iat 1031 is not yet valid. The token "eyJhbGciOiJub25lIn0.e30." has three parts in the base64url alphabet (the empty signature included), its header decodes to {"alg":"none"} and its payload to {}, so it passes the format check and is rejected at the algorithm step, before any claim is read.');
