-- challenge chal_quiz_nas_211 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_211', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-1' AND is_deleted = false LIMIT 1), 'hashed-refresh-tokens-quiz', 'What a hashed token store protects', 'Two pieces of evidence from the leaked-backup incident: a review comment that asks for bcrypt, and an attacker replaying a value copied from the backup.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211'), 'Pull request #911 "auth: store refresh tokens as hashes":

const token = randomBytes(32).toString("base64url");
const tokenHash = createHash("sha256").update(token).digest("hex");
await db.query("INSERT INTO auth.refresh_tokens (id, family_id, user_id, device_id, token_hash, created_at, expires_at) VALUES ($1, $2, $3, $4, $5, now(), now() + interval ''30 days'')", [id, familyId, userId, deviceId, tokenHash]);

Review comment: "SHA-256 is fast, so an attacker with the backup can brute-force these hashes. Use bcrypt with cost 12, like we do for passwords."

Statement: "The reviewer is right: with plain SHA-256, an attacker who has the backup can recover working refresh tokens from token_hash in practical time."', 'single_choice'::question_type, 'False. A slow, salted hash protects secrets that people choose, because those have little entropy and can be guessed from a dictionary. This token is 32 bytes from a cryptographic random generator: 256 bits, so there is no dictionary and an exhaustive search is out of reach even at billions of SHA-256 per second. bcrypt would also break the design: its salt makes the same token hash differently each time, so the server could no longer find the row with WHERE token_hash = $1 and would have to bcrypt-compare against every row, at about 0.25 s each. The misconception is that "fast hash" is a weakness by itself; it is a weakness only for low-entropy secrets such as passwords. OWASP''s Password Storage Cheat Sheet is about passwords, not about random tokens.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211'), 'After the fix, someone replays a value taken from the leaked backup (row rt_1842 of user u_ana):

$ curl -s -X POST https://api.codedev.test/auth/refresh \
    -H ''Content-Type: application/json'' \
    -d ''{"refreshToken":"9f2c4e0b7a1d...e85a"}''      # 64 hex characters: the token_hash column of rt_1842
{"error":"invalid_grant"}

API log: refresh_token.rejected reason=malformed

The server''s validate code checks the format (43 base64url characters), then runs SHA-256 over what it received and looks up WHERE token_hash = $1.

Statement: "Even if the format check were removed, this replay would fail, because the server would hash the 64 hex characters and SHA-256 of a hash matches no token_hash in the table."', 'single_choice'::question_type, 'True. The table stores H(token) and the server always computes H(presented). Presenting H(token) makes the server look up H(H(token)), which is not in the table, so the lookup finds nothing and the result is "unknown". That is the whole point of storing hashes: what is at rest is not what a client sends. The format check is a cheap early rejection and keeps junk out of the logs and the database, but security does not depend on it. The misconception is that a stolen hash can be "passed through" like a password hash in a pass-the-hash attack; that only works when the server accepts the hash itself as the credential.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_211') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nas_212 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_212', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-1' AND is_deleted = false LIMIT 1), 'store-refresh-tokens-as-hashes', 'Store refresh tokens as hashes', 'A copy of the CodeDev auth database leaked from a backup bucket, and the refresh tokens in it still worked: the table stored them in plain text. Write the two functions of the new token store so that the table only ever holds SHA-256 hashes.

issueRefreshToken(deps, userId, deviceId): create the token from deps.randomBytes(32).toString("base64url") (43 characters). Take id = deps.newId("rt") and then familyId = deps.newId("fam") (every issue starts a new family here). Insert one row with deps.store.insert: tokenHash = SHA-256 of the token as lowercase hex, createdAt = deps.now(), expiresAt = createdAt + deps.ttlMs, usedAt, revokedAt and replacedBy null. Log { event: "refresh_token.issued", id, userId, deviceId } and return { token, id, familyId, expiresAt }.

validateRefreshToken(deps, presented): presented comes straight from the request body and may be anything. Check in this order and return the first match: (1) not a string of exactly 43 characters from A-Z a-z 0-9 - _ -> { ok: false, reason: "malformed" } without touching the store; (2) hash it and call deps.store.findByHash(hash); no row, or a row whose tokenHash is not equal to the hash (compare the bytes with crypto.timingSafeEqual) -> "unknown"; (3) row.revokedAt is not null -> "revoked"; (4) deps.now() >= row.expiresAt -> "expired"; (5) otherwise { ok: true, id, familyId, userId, deviceId, expiresAt } of the row. Every rejection logs { event: "refresh_token.rejected", reason } with an id property added when a row was found (revoked, expired); a success logs { event: "refresh_token.accepted", id }. Log each event with these properties in this order.

A token or a stored hash must never appear in the store as plain text, in a log event or in a validate result. The test runner prints every operation with its log events, then the store (tokenHash shown as sha256(#n) when it is the hash of the n-th issued token, PLAIN(#n) when it is the token itself) and a leak check over the store, the logs and the results. Do not change the types, the store or the runner.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212'), 1, 'What exactly must the database hold so that a server can still recognise a token it issued, while a copy of the database gives an attacker nothing to send?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212'), 2, 'Look at three places: what you pass to store.insert (only tokenHash, never the token), the order of the checks in validate (format, lookup, revoked, expired), and every object you pass to deps.log or return from validate - none of them may carry the token or row.tokenHash.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212'), 3, 'A similar case with API keys: key = randomBytes(24).toString("base64url") gives 32 characters; the table keeps createHash("sha256").update(key).digest("hex"). To check a key, hash what the client sent, look up that hash, then compare Buffer.from(row.keyHash, "hex") with Buffer.from(hash, "hex") using timingSafeEqual (both 32 bytes). A key that was disabled yesterday is rejected as disabled before anyone looks at its expiry.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
