       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_212'), 'Revoked, expired and unknown tokens are rejected with their reason and logged without secrets', '{"ttlMs":2592000000,"ops":[{"op":"issue","userId":"u_ana","deviceId":"phone"},{"op":"issue","userId":"u_binh","deviceId":"web"},{"op":"issue","userId":"u_chi","deviceId":"tablet"},{"op":"revoke","id":"rt_2"},{"op":"advance","ms":2591999999},{"op":"validate","token":"#1"},{"op":"validate","token":"#2"},{"op":"advance","ms":1},{"op":"validate","token":"#1"},{"op":"validate","token":"#3"},{"op":"validate","token":"Zm9yZ2VkLXRva2VuLW5ldmVyLWlzc3VlZC1ieS11cyE"}]}', '"issue u_ana/phone -> rt_1 fam_1 token #1 expires 2026-11-25T08:00:00.000Z  log {\"event\":\"refresh_token.issued\",\"id\":\"rt_1\",\"userId\":\"u_ana\",\"deviceId\":\"phone\"}\nissue u_binh/web -> rt_2 fam_2 token #2 expires 2026-11-25T08:00:00.000Z  log {\"event\":\"refresh_token.issued\",\"id\":\"rt_2\",\"userId\":\"u_binh\",\"deviceId\":\"web\"}\nissue u_chi/tablet -> rt_3 fam_3 token #3 expires 2026-11-25T08:00:00.000Z  log {\"event\":\"refresh_token.issued\",\"id\":\"rt_3\",\"userId\":\"u_chi\",\"deviceId\":\"tablet\"}\nrevoke rt_2\nadvance to 2026-11-25T07:59:59.999Z\nvalidate #1 -> ok rt_1 fam_1 u_ana/phone until 2026-11-25T08:00:00.000Z  log {\"event\":\"refresh_token.accepted\",\"id\":\"rt_1\"}\nvalidate #2 -> revoked  log {\"event\":\"refresh_token.rejected\",\"reason\":\"revoked\",\"id\":\"rt_2\"}\nadvance to 2026-11-25T08:00:00.000Z\nvalidate #1 -> expired  log {\"event\":\"refresh_token.rejected\",\"reason\":\"expired\",\"id\":\"rt_1\"}\nvalidate #3 -> expired  log {\"event\":\"refresh_token.rejected\",\"reason\":\"expired\",\"id\":\"rt_3\"}\nvalidate \"Zm9yZ2VkLXRva2VuLW5ldmVyLWlzc3VlZC1ieS11cyE\" -> unknown  log {\"event\":\"refresh_token.rejected\",\"reason\":\"unknown\"}\nstore:\nrt_1 fam_1 u_ana/phone hash=sha256(#1) created 2026-10-26T08:00:00.000Z expires 2026-11-25T08:00:00.000Z revoked -\nrt_2 fam_2 u_bin