-- challenge chal_quiz_nas_221 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_221', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-2' AND is_deleted = false LIMIT 1), 'plaintext-tokens-migration-quiz', 'Moving a live table off plain-text tokens', 'Two pieces of evidence from the migration to hashed refresh tokens: a rolling deploy log and a one-line fix proposed in review.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221'), 'Rolling deploy of release 42 (hashed tokens) over 6 instances, 14:00-14:25:

14:00:12 api-1 release 42 ready     api-2..api-6 release 41
14:05:40 api-2 release 42 ready     api-3..api-6 release 41
...
14:24:58 api-6 release 42 ready

SELECT count(*) FROM auth.refresh_tokens WHERE token IS NOT NULL AND created_at > ''2026-10-26 14:00'';
 count
-------
  3114

Release 42 looks up refresh tokens only with WHERE token_hash = $1.

Statement: "About 3,100 learners who signed in during the deploy will get invalid_grant at their next refresh and have to sign in again."', 'single_choice'::question_type, 'True. During a rolling deploy both releases serve traffic. Every sign-in handled by a release 41 instance wrote a row with the plain token and no token_hash, and the query shows 3,114 such rows created after 14:00. Release 42 searches only by hash, finds nothing for those tokens and answers invalid_grant. That is why the new code must also read the legacy column for a while: find the row by its plain token, move it to the hash at once, and rotate. Only after the last old instance is gone does a backfill (UPDATE ... SET token_hash = encode(sha256(convert_to(token, ''UTF8'')), ''hex''), token = NULL) clear the remaining rows, and a later release drops the column. The misconception is that a schema change and a code change switch over at one instant.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221'), 'The incident: a database backup with auth.refresh_tokens leaked, and its tokens worked. A proposed fix in review:

-  if (!row || row.token !== presented) return { ok: false, reason: "unknown" };
+  if (!row || !timingSafeEqual(Buffer.from(row.token), Buffer.from(presented))) {
+    return { ok: false, reason: "unknown" };
+  }

"Constant-time comparison closes the leak."

Statement: "After this change, a token copied from that backup stops working."', 'single_choice'::question_type, 'False. timingSafeEqual removes a timing side channel: an attacker probing the API cannot learn a token byte by byte from response times. It does nothing about secrets at rest. The backup holds the plain token, the table still holds it, and presenting it gives an exact match whichever comparison is used. Two changes close the incident: store only SHA-256 of the token, and rotate on every refresh so the copies in old backups are already used. Also note that timingSafeEqual throws when the two buffers have different lengths, so comparing raw strings needs a length check (or comparing fixed-size hashes). The misconception is that "constant-time" means "secure storage".', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_221') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nas_222 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_222', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-2' AND is_deleted = false LIMIT 1), 'fix-plaintext-refresh-tokens', 'Fix it: refresh tokens stored in plain text', 'Incident CODEDEV-1907: a copy of auth.refresh_tokens leaked from a backup bucket and the refresh tokens in it still worked, some of them months after they were issued. The token service in the starter is the code that was running. It writes every refresh token into the plain-text column token, finds it with WHERE token = $1 and compares with !==, and refresh hands back the same token with its expiry pushed forward, so a copied token never stops working. Release 42 must fix all of that while release 41 instances keep writing plain-text rows until the rolling deploy is finished.

login(deps, userId, deviceId): keep the order id = deps.newId("rt"), then familyId = deps.newId("fam"), token from deps.randomBytes(32).toString("base64url"). Insert the row with token = null and tokenHash = SHA-256 of the token as lowercase hex, createdAt = deps.now(), expiresAt = createdAt + deps.ttlMs. Return { token, id, familyId, expiresAt } as before.

refresh(deps, presented), checked in this order: (1) not a 43-character base64url string -> "malformed". (2) Hash it and look it up with deps.store.findByHash; compare the stored and computed hashes with crypto.timingSafeEqual. (3) Migration path - no row by hash: look it up with deps.store.findByPlainToken (compare the bytes with timingSafeEqual too). No row either way -> "unknown". When the row is found this way, immediately update it to token = null and tokenHash = the hash, whatever the result of the remaining checks, so a legacy token is never left in plain text once it has been presented. (4) row.revokedAt not null -> "revoked"; (5) row.usedAt not null -> "used"; (6) deps.now() >= row.expiresAt -> "expired". (7) Rotate: take id = deps.newId("rt"), insert a new row in the same family for the same user and device (new random token, token = null, tokenHash = its hash, createdAt = now, expiresAt = now + ttlMs, usedAt, revokedAt and replacedBy null), then update the old row to usedAt = now and replacedBy = the new id. Return { ok: true, token, id, familyId, expiresAt } of the new token. Failures return { ok: false, reason }.

The test runner seeds legacy rows (L1, L2 ...), runs the operations and prints the store after each one: tokenHash shows as sha256(#n) or sha256(L1) and the token column as PLAIN(...) when it holds a token. It ends with every token still stored in plain text or returned in a result. Do not change the types, the store or the runner.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
