INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_222'), 1, 'Look at the store dump after login and after a refresh: which column holds the token, and which token does the client hold afterwards? Would a copy of this table from last month still sign someone in?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_222'), 2, 'Three places: the row inserted by login (token versus tokenHash), the lookup at the top of refresh (only findByPlainToken today), and the end of refresh, which updates expiresAt on the old row instead of creating a new one. For the migration, the legacy lookup belongs after the hash lookup, and the legacy row must be moved to its hash before the revoked, used and expired checks.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_222'), 3, 'A similar migration for API keys: a request with key K first runs findByHash(sha256(K)). Not found, it tries findByPlainKey(K); found, it immediately writes keyHash = sha256(K) and key = null on that row, then applies the usual checks. A second request with K now finds the row by hash, and a SELECT on the key column no longer shows K - even if the first request was rejected because the key had expired.');
