INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_222'), 'Sign in stores only the hash; each refresh returns a new token and marks the old row used', '{"ttlMs":2592000000,"ops":[{"op":"login","userId":"u_ana","deviceId":"phone"},{"op":"advance","ms":3600000},{"op":"refresh","token":"#1"},{"op":"advance","ms":3600000},{"op":"refresh","token":"#2"}]}', '"login u_ana/phone -> rt_1 fam_1 token #1 expires 2026-11-25T08:00:00.000Z\n  rt_1 fam_1 u_ana/phone hash=sha256(#1) token=- expires 2026-11-25T08:00:00.000Z used - revoked - replacedBy -\nadvance to 2026-10-26T09:00:00.000Z\n  rt_1 fam_1 u_ana/phone hash=sha256(#1) token=- expires 2026-11-25T08:00:00.000Z used - revoked - replacedBy -\nrefresh #1 -> ok rt_2 fam_1 token #2 expires 2026-11-25T09:00:00.000Z\n  rt_1 fam_1 u_ana/phone hash=sha256(#1) token=- expires 2026-11-25T08:00:00.000Z used 2026-10-26T09:00:00.000Z revoked - replacedBy rt_2\n  rt_2 fam_1 u_ana/phone hash=sha256(#2) token=- expires 2026-11-25T09:00:00.000Z used - revoked - replacedBy -\nadvance to 2026-10-26T10:00:00.000Z\n  rt_1 fam_1 u_ana/phone hash=sha256(#1) token=- expires 2026-11-25T08:00:00.000Z used 2026-10-26T09:00:00.000Z revoked - replacedBy rt_2\n  rt_2 fam_1 u_ana/phone hash=sha256(#2) token=- expires 2026-11-25T09:00:00.000Z used - revoked - replacedBy -\nrefresh #2 -> ok rt_3 fam_1 token #3 expires 2026-11-25T10:00:00.000Z\n  rt_1 fam_1 u_ana/phone hash=sha256(#1) token=- expires 2026-11-25T08:00:00.000Z used 2026-10-26T09:00:00.000Z revoked - replacedBy rt_2\n  rt_2 fam_1 u_ana/phone hash=sha256(#2) token=- expires 2026-11-25T09:00:00.000Z used 2026-10-26T10:00:00.000Z revoked - replacedBy rt_3\n  rt_3 fam_1 u_ana/phone hash=sha256(#3) token=- expires 2026-11-25T10:00:00.000Z used - revoked - replacedBy -\nplain text: none"', 3, true, false, 1),
