       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_222'), 'Legacy rows that are expired, revoked or already used are rejected and still lose their plain text', '{"ttlMs":2592000000,"legacy":[{"id":"rt_911","familyId":"fam_911","userId":"u_eve","deviceId":"phone","token":"eiz7n2VpPEf_9gaAwqzzyIVSLIAtvTBOqzapjp7hZQI","createdAt":1790323200000,"expiresAt":1792915200000},{"id":"rt_912","familyId":"fam_912","userId":"u_eve","deviceId":"laptop","token":"-AsY6YKtoSIu5SdZ78lGplrBAV5QPyosB9iIIRUU_oY","createdAt":1792828800000,"expiresAt":1795420800000,"revokedAt":1792915200000},{"id":"rt_913","familyId":"fam_913","userId":"u_fai","deviceId":"web","token":"-5wzO6Kgn9wJZe-wiWQUb-1OIeJaxmv0VACaGjMro2k","createdAt":1792656000000,"expiresAt":1795248000000,"usedAt":1792742400000},{"id":"rt_914","familyId":"fam_914","userId":"u_gia","deviceId":"web","token":"DSct5ELfcvepRxj8t3_TysfizvuGl5yMOzEKyvBiKGA","createdAt":1792137600000,"expiresAt":1794729600000}],"ops":[{"op":"refresh","token":"L1"},{"op":"refresh","token":"L2"},{"op":"refresh","token":"L3"},{"op":"refresh","token":"L1"},{"op":"revoke","id":"rt_914"},{"op":"refresh","token":"L4"}]}', '"refresh L1 -> expired\n  rt_911 fam_911 u_eve/phone hash=sha256(L1) token=- expires 2026-10-25T08:00:00.000Z used - revoked - replacedBy -\n  rt_912 fam_912 u_eve/laptop hash=- token=PLAIN(L2) expires 2026-11-23T08:00:00.000Z used - revoked 2026-10-25T08:00:00.000Z replacedBy -\n  rt_913 fam_913 u_fai/web hash=- token=PLAIN(L3) expires 2026-11-21T08:00:00.000Z used 2026-10-23T08:00:00.000Z revoked - replacedBy -\n  rt_914 fam_914 u_gia/web hash=- token=PLAIN(L4) expires 2026-11-15T08:00:00.000Z used - revoked - replacedBy -\nrefresh L2 -> revoked\n  rt_911 fam_911 u_eve/phone hash=sha256(L1) token=- expires 2026-10-25T08:00:00.000Z used - revoked - replacedBy -\n  rt_912 fam_912 u_eve/laptop hash=sha256(L2) token=- expires 2026-11-23T08:00:00.000Z used - revoked 2026-10-25T08:00:00.000Z replacedBy -\n  rt_913 fam