-- challenge chal_quiz_nas_231 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_231', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-3' AND is_deleted = false LIMIT 1), 'rotation-families-quiz', 'Reading a token family', 'Two pieces of evidence from the rotation work: a pull request that adds an absolute session lifetime, and a refresh that was rejected as used.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231'), 'Pull request #1290 "auth: absolute session lifetime" (IDLE_TIMEOUT_MS = 14 days, ABSOLUTE_LIFETIME_MS = 30 days), inside refresh() after the revoked and used checks; row is the presented token:

+  const familyDeadline = row.createdAt + ABSOLUTE_LIFETIME_MS;
+  if (now >= familyDeadline) return { ok: false, reason: "family_expired" };
   if (now >= row.expiresAt) return { ok: false, reason: "idle_timeout" };
   const next = await this.tokens.insert({
     familyId: row.familyId, userId: row.userId, deviceId: row.deviceId,
     tokenHash: sha256Hex(newToken), createdAt: now,
-    expiresAt: now + IDLE_TIMEOUT_MS,
+    expiresAt: Math.min(now + IDLE_TIMEOUT_MS, familyDeadline),
   });

Statement: "After this change, a client that refreshes every 6 days must sign in again at the latest 30 days after its login."', 'single_choice'::question_type, 'False. row is the presented token, and its createdAt is the moment of the previous refresh, not of the login. So familyDeadline moves 6 days forward at every refresh, the check never fires, and the cap is always later than now + 14 days: the session slides forever, exactly as before the change. The absolute lifetime has to start at the family''s first token: the smallest created_at in the family (or a started_at stored on a family row), and every new token''s expires_at is capped at that start + 30 days. A test that refreshes every 6 days and expects family_expired at day 30 catches this immediately. The misconception is that any "createdAt + lifetime" check is an absolute timeout; it is only absolute if the createdAt never changes. RFC 9700 (section 4.14.2) says refresh tokens should expire after a period of inactivity, and the OWASP Session Management Cheat Sheet asks for both an idle timeout and an absolute timeout.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231'), 'Family fam_7 of u_binh (laptop), idle timeout 14 days, absolute lifetime 30 days, now = 2026-10-26 12:00:

 id   | created_at       | expires_at       | used_at          | revoked_at | replaced_by
------+------------------+------------------+------------------+------------+------------
 rt_7 | 2026-10-20 09:00 | 2026-11-03 09:00 | 2026-10-24 18:30 |            | rt_8
 rt_8 | 2026-10-24 18:30 | 2026-11-07 18:30 | 2026-10-26 11:58 |            | rt_9
 rt_9 | 2026-10-26 11:58 | 2026-11-09 11:58 |                  |            |

API log at 12:00: POST /auth/refresh token=rt_8 -> 401 {"error":"invalid_grant","reason":"used"}

Statement: "rt_9 is the only token of fam_7 that the server will exchange now."', 'single_choice'::question_type, 'True. Rotation keeps exactly one live token per family: rt_7 was replaced by rt_8, rt_8 by rt_9, and both have used_at set, so the server rejects them as used. rt_9 is unused, not revoked, not past its expires_at (2026-11-09 11:58) and the family started on 2026-10-20 09:00, well inside the 30-day lifetime. The replaced_by chain (rt_7 -> rt_8 -> rt_9) is what lets you read the history of one sign-in. Who sent rt_8 again at 12:00 - a second tab that missed the response, or someone who copied the token - is the question of the next two lessons; this table cannot tell them apart. The misconception is that an old token keeps working until its own expires_at.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_231') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nas_232 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_232', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 2 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-2-3' AND is_deleted = false LIMIT 1), 'refresh-token-rotation-families', 'Refresh token rotation with token families', 'Since hashed tokens shipped, CodeDev''s refresh tokens are safe at rest, but a refresh token still lives forever: each refresh pushes the expiry forward, and one family in production has been refreshed 412 times since March. Write login and refresh so that every sign-in is a token family with an idle timeout and an absolute lifetime.

login(deps, userId, deviceId): always a new family, even for a device that already has one. id = deps.newId("rt"), then familyId = deps.newId("fam"), token = deps.randomBytes(32).toString("base64url"). familyExpiresAt = now + deps.absoluteLifetimeMs; the row gets tokenHash = sha256Hex(token), createdAt = now, expiresAt = min(now + deps.idleTimeoutMs, familyExpiresAt), usedAt, revokedAt and replacedBy null. Return the Session { token, id, familyId, userId, deviceId, expiresAt, familyExpiresAt }.

refresh(deps, presented): return the first match: (1) not a 43-character base64url string -> "malformed"; (2) no row for sha256Hex(presented) via deps.store.findByHash (compare the hashes with timingSafeEqual) -> "unknown"; (3) row.revokedAt not null -> "revoked"; (4) row.usedAt not null -> "used" (no other change: replay detection is the next lesson); (5) the family started at the smallest createdAt of deps.store.findFamily(row.familyId); familyExpiresAt = that start + absoluteLifetimeMs; now >= familyExpiresAt -> "family_expired"; (6) now >= row.expiresAt -> "idle_timeout"; (7) rotate: id = deps.newId("rt"), insert a new row in the same family for the same user and device with createdAt = now and expiresAt = min(now + idleTimeoutMs, familyExpiresAt), then update the presented row to usedAt = now and replacedBy = the new id. Return { ok: true, ...the new Session }. Failures return { ok: false, reason } and change nothing.

The tests run logins and refreshes for several users and devices over a fake clock (times print as days and hours after the start, d2 03:00) and print each result, then the store and a leak check. Do not change the types, the store, the helpers TOKEN_FORMAT and sha256Hex or the runner.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_232');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_232'), 1, 'Two clocks run for every token: one that restarts at each refresh and one that never restarts. Where does each one start, and which of them can you compute from the presented row alone?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_232'), 2, 'The idle clock is the presented row''s expiresAt. The absolute clock starts at the first token of the family, which is not the row you were given: look at what deps.store.findFamily returns. Then look at the expiresAt you write for the new token: what happens when the family has less time left than idleTimeoutMs?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_232'), 3, 'A worked trace with idle 10 h and absolute 24 h: login at 00:00 gives expiresAt 10:00 and family until d1 00:00. Refresh at 09:00 -> new token expires 19:00. Refresh at 18:00 -> min(d1 04:00, d1 00:00) = d1 00:00. A refresh at d1 00:00 is family_expired, not idle_timeout, even though that token''s own expiry has also passed. Presenting the 09:00 token again at 12:00 is used, and the family is left as it was.');
