-- challenge chal_quiz_nas_311 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_311', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-3-1' AND is_deleted = false LIMIT 1), 'replay-detection-evidence', 'Replay detection: read the rows and the log', 'Two statements on real refresh_tokens rows and API logs: what to revoke when a rotated token comes back, and when a reuse is only a network retry.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311'), 'Family f_12 after an alert (refresh tokens rotate on every refresh):

SELECT id, device_id, used_at, revoked_at, replaced_by
FROM refresh_tokens WHERE family_id = ''f_12'' ORDER BY created_at;

 id   | device_id | used_at             | revoked_at | replaced_by
 r_40 | phone-31  | 2026-10-20 08:00:05 |            | r_41
 r_41 | phone-31  | 2026-10-20 08:15:09 |            | r_42
 r_42 | phone-31  |                     |            |

API log:
2026-10-20 08:31:44 POST /auth/refresh token_id=r_40 device=phone-31 ip=203.0.113.50 reuse=true

Statement: "Revoking only r_40, the token that was presented again, is enough: r_42 is the phone''s current token, so it is safe to leave it valid."', 'single_choice'::question_type, 'False. r_40 came back about 31 minutes after it was rotated (and after a second rotation), so at least two parties held a copy of it. The server cannot tell who performed the rotations r_40 -> r_41 -> r_42: if an attacker stole r_40 and refreshed first, the attacker holds r_42 and the learner is the one presenting r_40 now; it could also be the other way round. r_40 is already useless (it is used), so revoking it alone changes nothing. The safe answer is to revoke the whole family, r_42 included, record a security event and let the real learner sign in again. The misconception is that whoever presents the old token must be the attacker.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311'), 'API log, one phone with a 2 s client timeout:

10:00:00.000 POST /auth/refresh device=phone-8812 token_id=r_77 -> 200 rotated, issued r_78
10:00:02.000 client: request timed out, retrying
10:00:02.410 POST /auth/refresh device=phone-8812 token_id=r_77

Config: REFRESH_GRACE_MS=10000. At 10:00:02.410, r_77 has used_at 10:00:00.000 and replaced_by r_78; r_78 has used_at NULL and revoked_at NULL.

Statement: "With this grace window, the retry receives the refresh token already issued as r_78, no new row is inserted, and no security event is recorded."', 'single_choice'::question_type, 'True. The reuse comes from the same device 2.41 s after r_77 was used, inside the 10 s window, and the successor r_78 has not been used or revoked, so this looks like a lost response, not a second party. The server answers with the successor it already issued (kept for the window), so the family does not fork and the phone ends up with the one live token. Two misconceptions: that every reuse must revoke the family (every slow network would sign learners out), and that a retry should get a brand-new token (that creates a second live branch in the family).', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_311') AND order_index = 2)
    RETURNING id
)
