        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nas_312 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_312', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-3-1' AND is_deleted = false LIMIT 1), 'refresh-token-replay-detection', 'Replay Detection: Revoke the Family', 'CodeDev rotates the refresh token on every POST /auth/refresh, but when a token that was already rotated comes back, the API only answers 401 and leaves the rest of the family alive. A copy stolen from a learner''s laptop was used once more after the learner had rotated it, and the attacker''s own chain kept working. Write refresh(store, req) with replay detection.

Look the row up by sha256(token) (hex, helper given). Check in this order: (1) no row -> {status:"invalid"}; (2) revokedAt set -> {status:"revoked"}; (3) req.now >= expiresAt -> {status:"expired"}; (4) unused row -> claim it with store.markUsed (a compare-and-swap: UPDATE ... SET used_at = $2 WHERE id = $1 AND used_at IS NULL AND revoked_at IS NULL RETURNING *), issue the successor in the same family for the row''s user and device with store.issue, link it with store.recordSuccessor and return {status:"rotated", token}; if issue returns null (family revoked) return {status:"revoked"}; (5) used row (a reuse) -> grace when the request comes from the row''s device, less than GRACE_MS = 10000 ms after usedAt (10000 ms is outside), and the successor row (replacedBy) is neither used nor revoked: return {status:"grace", token: store.getReply(row.id)}, the successor already issued, and create nothing. Any other reuse is a replay: revoke the whole family with store.revokeFamily, record one security event {type:"refresh_token_reuse", userId, familyId, tokenId: the presented row id, deviceId: req.deviceId, at: req.now} and return {status:"replay_detected"}.

Input: {"steps": [...], "quiet"?: true}; a step is {op:"login", user, device, at} (a new family) or {op:"refresh", token, device, at}, where token is a label ("t3" = the token of row r3) or a literal string. Times are milliseconds on a fake clock; tokens live 14 days. Output: one line per step ("refresh t1 laptop @3600000: replay_detected", "... rotated t2"), then one line per security event and one per row ("r1 f1 phone used=60000 revoked=- next=r2"); with quiet, a summary instead of the step and row lines.', 'open', 'hard'::difficulty_question, 'mini_coding', 40, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
