INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 1, 'When a token that was already rotated comes back, can the server tell which of the two callers is the real learner? If not, which tokens of the family could the other caller be holding right now?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 2, 'Everything you need for a reuse is on the presented row and its successor: row.usedAt (when the window started), row.deviceId, row.replacedBy (load it with store.findById to see whether it was used) and store.getReply(row.id). Check the cheap grace conditions first and let everything else fall through to the alarm.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 3, 'A similar rule on different data: a one-time sign-in link c1 is used at 12:00:00 and creates session s2. The same browser opens c1 again at 12:00:03 while s2 is untouched: show s2 again and create nothing. Another browser opens c1, or s2 was already used, or it is 12:00:30: end every session that came from c1 and log one alert with the link id, the browser and the time.');
