VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 'Reuse from another device after rotation revokes the whole family', '{"steps":[{"op":"login","user":"u_8812","device":"phone","at":0},{"op":"refresh","token":"t1","device":"phone","at":60000},{"op":"refresh","token":"t1","device":"laptop","at":3600000},{"op":"refresh","token":"t2","device":"phone","at":3660000}]}', '"login u_8812 phone: t1\nrefresh t1 phone @60000: rotated t2\nrefresh t1 laptop @3600000: replay_detected\nrefresh t2 phone @3660000: revoked\nevent refresh_token_reuse user=u_8812 family=f1 token=r1 device=laptop at=3600000\nr1 f1 phone used=60000 revoked=3600000 next=r2\nr2 f1 phone used=- revoked=3600000 next=-"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 'A retry from the same device within 10 s gets the successor already issued', '{"steps":[{"op":"login","user":"u_8812","device":"phone","at":0},{"op":"refresh","token":"t1","device":"phone","at":60000},{"op":"refresh","token":"t1","device":"phone","at":64000},{"op":"refresh","token":"t2","device":"phone","at":900000},{"op":"refresh","token":"t3","device":"phone","at":1800000}]}', '"login u_8812 phone: t1\nrefresh t1 phone @60000: rotated t2\nrefresh t1 phone @64000: grace t2\nrefresh t2 phone @900000: rotated t3\nrefresh t3 phone @1800000: rotated t4\nr1 f1 phone used=60000 revoked=- next=r2\nr2 f1 phone used=900000 revoked=- next=r3\nr3 f1 phone used=1800000 revoked=- next=r4\nr4 f1 phone used=- revoked=- next=-"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_312'), 'The window ends at 10 s: 9999 ms is a retry, 10000 ms is a replay', '{"steps":[{"op":"login","user":"u_8812","device":"phone","at":0},{"op":"refresh","token":"t1","device":"phone","at":60000},{"op":"refresh","token":"t1","device":"phone","at":69999},{"op":"refresh","token":"t1","device":"phone","at":70000},{"op":"refresh","token":"t2","device":"phone","at":71000}]}', '"login u_8812 phone: t1\nrefresh t1 phone @60000: rotated t2\nrefresh t1 phone @69999: grace t2\nrefresh t1 phone @70000: replay_detected\nrefresh t2 phone @71000: revoked\nevent refresh_token_reuse user=u_8812 family=f1 token=r1 device=phone at=70000\nr1 f1 phone used=60000 revoked=70000 next=r2\nr2 f1 phone used=- revoked=70000 next=-"', 2, false, true, 3),
