-- challenge chal_quiz_nas_321 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_321', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 3 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-3-2' AND is_deleted = false LIMIT 1), 'concurrent-refresh-evidence', 'Concurrent Refresh & Token Replay: read the evidence', 'A learner''s phone resumed, refreshed twice with the same token 40 ms apart, got two 200 responses, and 15 minutes later was flagged as a replay and signed out on every device. Six statements on one evidence pack - the API log (A), the refresh code (B), the PostgreSQL statement log (C) and the rows of the family (D) - take you from the evidence to a hypothesis, past two wrong explanations, to the fix and its test.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
