-- challenge chal_coding_nas_412 (mini_coding)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_412', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-4-1' AND is_deleted = false LIMIT 1), 'sign-out-one-device-or-all', 'Sign out one device or all devices', 'The Settings page of https://app.codedev.test gets a Sessions section: a list of the learner''s devices, "Sign out" next to each one, and "Sign out of all devices", which the password change also triggers. A session is a refresh token family: one familyId per sign-in on one device, rows shaped like { id, familyId, userId, deviceId, tokenHash, createdAt, expiresAt, usedAt, revokedAt, replacedBy }. Access tokens live 15 minutes (ACCESS_TTL_MS) and carry the decoded claims { sub, sid, ver, iat, exp }: sub = userId, sid = familyId, ver = the user''s session version when the token was issued. Sign-in and rotation (with replay detection) are already written; write the five functions they rely on.

revokeFamily(s, userId, familyId, now): if no row of familyId belongs to userId (unknown family or another user''s), return false and change nothing. Otherwise set revokedAt = now on every row of the family whose revokedAt is null; if at least one row changed, put the family on the deny list with s.deniedFamilies.set(familyId, now + ACCESS_TTL_MS). Return true (also for a family that was already revoked).

signOutAll(s, userId, now): bump the user''s session version (s.sessionVersion, a missing user counts as 0) by 1, set revokedAt = now on every row of the user whose revokedAt is null, and add nothing to the deny list.

checkAccess(s, claims, now) runs on every API request and may use only the two maps, never s.rows: now >= claims.exp -> "expired"; claims.ver lower than the user''s session version -> "revoked"; claims.sid on the deny list -> "revoked"; otherwise "ok".

pruneDenyList(s, now): delete every deny-list entry whose time is <= now. The runner calls it before every operation, so the list only holds families revoked in the last 15 minutes.

listSessions(s, userId, now): one entry per family of the user that has a live row (usedAt null, revokedAt null, now < expiresAt), with its deviceId, createdAt = the smallest createdAt of the family''s rows and lastUsedAt = the largest. Sort by lastUsedAt, newest first, then by familyId ascending (plain string comparison).

Input: a JSON list of operations in time order, with "at" in minutes on a fake clock (login, refresh, api, logout, revoke, logoutAll, passwordChanged, sessions, denylist; see the test runner). Output: one line per operation. Times are whole minutes; up to 1000 operations.', 'open', 'medium'::difficulty_question, 'mini_coding', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412');
INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 1, 'Revoking rows in the table stops the next refresh. What stops an access token that was issued two minutes before the sign-out, and how long does that thing need to remember the family?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 2, 'Look at what each operation must change: revokeFamily touches the family''s rows and the deny list, signOutAll touches the user''s rows and the session version, checkAccess only reads the two maps. In listSessions, group the user''s rows by familyId before you decide whether a family is live.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 3, 'A similar case on other data: a course pass is revoked at minute 40 and passes are valid for 10 minutes, so an entry in a revoked-passes map with time 40 + 10 = 50 is enough; at minute 50 the pass has expired by itself and the entry can go. A user-wide counter does the same job for "revoke everything": passes that carry an older counter value are rejected, with no entry per pass.');
INSERT INTO challenge.coding_configs (challenge_id, execution_mode, time_limit_ms, memory_limit_mb, max_attempts, scoring_mode)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'stdio', 3000, 128, NULL, 'all_or_nothing')
ON CONFLICT (challenge_id) DO UPDATE SET
    execution_mode = EXCLUDED.execution_mode, time_limit_ms = EXCLUDED.time_limit_ms, memory_limit_mb = EXCLUDED.memory_limit_mb,
    max_attempts = EXCLUDED.max_attempts, scoring_mode = EXCLUDED.scoring_mode, updated_at = now();
DELETE FROM challenge.challenge_test_cases WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412');
INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'Sign out this device: its tokens stop at once, the other device keeps working', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":1,"op":"login","user":"u1","device":"laptop"},{"at":2,"op":"api","access":"A1"},{"at":3,"op":"logout","access":"A1"},{"at":3,"op":"api","access":"A1"},{"at":4,"op":"refresh","refresh":"R1"},{"at":4,"op":"api","access":"A2"},{"at":5,"op":"sessions","access":"A2"},{"at":5,"op":"denylist"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[1m] login u1 laptop: fam_2, A2, R2\n[2m] api A1: 200\n[3m] logout A1: 204\n[3m] api A1: 401 revoked\n[4m] refresh R1: 401 revoked\n[4m] api A2: 200\n[5m] sessions A2: fam_2 laptop since 1m last 1m (this device)\n[5m] deny list: 1 (fam_1)"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'Sessions list: device, sign-in and last refresh, newest first, only the caller''s sessions', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":5,"op":"login","user":"u1","device":"laptop"},{"at":6,"op":"login","user":"u2","device":"tablet"},{"at":20,"op":"sessions","access":"A3"},{"at":20,"op":"refresh","refresh":"R1"},{"at":21,"op":"sessions","access":"A4"},{"at":30,"op":"refresh","refresh":"R2"},{"at":31,"op":"sessions","access":"A5"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[5m] login u1 laptop: fam_2, A2, R2\n[6m] login u2 tablet: fam_3, A3, R3\n[20m] sessions A3: fam_3 tablet since 6m last 6m (this device)\n[20m] refresh R1: A4, R4\n[21m] sessions A4: fam_1 phone since 0m last 20m (this device); fam_2 laptop since 5m last 5m\n[30m] refresh R2: A5, R5\n[31m] sessions A5: fam_2 laptop since 5m last 30m (this device); fam_1 phone since 0m last 20m"', 3, true, false, 2),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'Password change signs out every device of the user and adds nothing to the deny list', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":1,"op":"login","user":"u1","device":"laptop"},{"at":2,"op":"login","user":"u1","device":"tablet"},{"at":2,"op":"login","user":"u2","device":"phone"},{"at":3,"op":"refresh","refresh":"R1"},{"at":4,"op":"passwordChanged","user":"u1"},{"at":4,"op":"api","access":"A5"},{"at":4,"op":"api","access":"A2"},{"at":4,"op":"api","access":"A3"},{"at":5,"op":"refresh","refresh":"R5"},{"at":5,"op":"refresh","refresh":"R2"},{"at":5,"op":"refresh","refresh":"R3"},{"at":5,"op":"api","access":"A4"},{"at":5,"op":"denylist"},{"at":6,"op":"login","user":"u1","device":"phone"},{"at":6,"op":"api","access":"A6"},{"at":6,"op":"sessions","access":"A6"},{"at":7,"op":"logoutAll","access":"A6"},{"at":7,"op":"api","access":"A6"},{"at":7,"op":"refresh","refresh":"R6"},{"at":7,"op":"api","access":"A4"},{"at":7,"op":"denylist"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[1m] login u1 laptop: fam_2, A2, R2\n[2m] login u1 tablet: fam_3, A3, R3\n[2m] login u2 phone: fam_4, A4, R4\n[3m] refresh R1: A5, R5\n[4m] password changed u1\n[4m] api A5: 401 revoked\n[4m] api A2: 401 revoked\n[4m] api A3: 401 revoked\n[5m] refresh R5: 401 revoked\n[5m] refresh R2: 401 revoked\n[5m] refresh R3: 401 revoked\n[5m] api A4: 200\n[5m] deny list: 0\n[6m] login u1 phone: fam_5, A6, R6\n[6m] api A6: 200\n[6m] sessions A6: fam_5 phone since 6m last 6m (this device)\n[7m] logoutAll A6: 204\n[7m] api A6: 401 revoked\n[7m] refresh R6: 401 revoked\n[7m] api A4: 200\n[7m] deny list: 0"', 3, false, true, 3),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'Revoking another user''s session or an unknown family returns 404 and changes nothing', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":0,"op":"login","user":"u2","device":"laptop"},{"at":1,"op":"login","user":"u1","device":"laptop"},{"at":2,"op":"revoke","access":"A1","family":"fam_2"},{"at":2,"op":"api","access":"A2"},{"at":2,"op":"refresh","refresh":"R2"},{"at":2,"op":"revoke","access":"A1","family":"fam_99"},{"at":3,"op":"revoke","access":"A1","family":"fam_3"},{"at":3,"op":"api","access":"A3"},{"at":4,"op":"revoke","access":"A1","family":"fam_3"},{"at":4,"op":"denylist"},{"at":4,"op":"sessions","access":"A1"},{"at":4,"op":"sessions","access":"A4"},{"at":17,"op":"denylist"},{"at":18,"op":"denylist"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[0m] login u2 laptop: fam_2, A2, R2\n[1m] login u1 laptop: fam_3, A3, R3\n[2m] revoke A1 fam_2: 404\n[2m] api A2: 200\n[2m] refresh R2: A4, R4\n[2m] revoke A1 fam_99: 404\n[3m] revoke A1 fam_3: 204\n[3m] api A3: 401 revoked\n[4m] revoke A1 fam_3: 204\n[4m] deny list: 1 (fam_3)\n[4m] sessions A1: fam_1 phone since 0m last 0m (this device)\n[4m] sessions A4: fam_2 laptop since 0m last 2m (this device)\n[17m] deny list: 1 (fam_3)\n[18m] deny list: 0"', 3, false, true, 4),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'A deny-list entry lives exactly 15 minutes, then the old access token fails as expired', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":10,"op":"refresh","refresh":"R1"},{"at":10,"op":"login","user":"u1","device":"laptop"},{"at":10,"op":"logout","access":"A2"},{"at":24,"op":"api","access":"A2"},{"at":24,"op":"api","access":"A3"},{"at":24,"op":"denylist"},{"at":24,"op":"logout","access":"A3"},{"at":25,"op":"denylist"},{"at":25,"op":"api","access":"A2"},{"at":38,"op":"denylist"},{"at":39,"op":"denylist"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[10m] refresh R1: A2, R2\n[10m] login u1 laptop: fam_2, A3, R3\n[10m] logout A2: 204\n[24m] api A2: 401 revoked\n[24m] api A3: 200\n[24m] deny list: 1 (fam_1)\n[24m] logout A3: 204\n[25m] deny list: 1 (fam_2)\n[25m] api A2: 401 expired\n[38m] deny list: 1 (fam_2)\n[39m] deny list: 0"', 3, false, true, 5),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'A replayed refresh token revokes its family, including the access token just issued', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":0,"op":"login","user":"u1","device":"laptop"},{"at":5,"op":"refresh","refresh":"R1"},{"at":6,"op":"refresh","refresh":"R1"},{"at":6,"op":"api","access":"A3"},{"at":7,"op":"refresh","refresh":"R3"},{"at":7,"op":"denylist"},{"at":7,"op":"sessions","access":"A2"},{"at":7,"op":"api","access":"A2"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[0m] login u1 laptop: fam_2, A2, R2\n[5m] refresh R1: A3, R3\n[6m] refresh R1: 401 replay\n[6m] api A3: 401 revoked\n[7m] refresh R3: 401 revoked\n[7m] deny list: 1 (fam_1)\n[7m] sessions A2: fam_2 laptop since 0m last 0m (this device)\n[7m] api A2: 200"', 3, false, true, 6),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_412'), 'Refresh tokens expire after 14 days and their session leaves the list', '[{"at":0,"op":"login","user":"u1","device":"phone"},{"at":10000,"op":"login","user":"u1","device":"laptop"},{"at":20000,"op":"refresh","refresh":"R2"},{"at":20150,"op":"refresh","refresh":"R3"},{"at":20159,"op":"sessions","access":"A4"},{"at":20160,"op":"sessions","access":"A4"},{"at":20160,"op":"refresh","refresh":"R1"},{"at":20161,"op":"refresh","refresh":"R4"}]', '"[0m] login u1 phone: fam_1, A1, R1\n[10000m] login u1 laptop: fam_2, A2, R2\n[20000m] refresh R2: A3, R3\n[20150m] refresh R3: A4, R4\n[20159m] sessions A4: fam_2 laptop since 10000m last 20150m (this device); fam_1 phone since 0m last 0m\n[20160m] sessions A4: fam_2 laptop since 10000m last 20150m (this device)\n[20160m] refresh R1: 401 expired\n[20161m] refresh R4: A5, R5"', 2, false, true, 7),
