INSERT INTO challenge.challenge_hints (challenge_id, level, body)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_422'), 1, 'For each value the response hands to the browser, ask two questions: who can read it (scripts on app.codedev.test, the forum, only the API) and who needs to read it. Which of the three values does the SPA itself actually need?'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_422'), 2, 'Look at the shared attribute string the assistant reused for both cookies, and at the last property of the response body. A Domain attribute makes a cookie go to every subdomain; leaving it out makes it host-only. Then check the prefix rules: __Host- allows only Path=/ and no Domain, __Secure- only requires Secure.'),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_422'), 3, 'A similar case on another endpoint: an instructor-preview cookie that only https://api.codedev.test/preview should receive would be `preview_grant=...; HttpOnly; Secure; SameSite=Strict; Path=/preview; Max-Age=600` with no Domain, while a theme cookie the SPA reads on every subdomain would be `theme=dark; Domain=codedev.test; Path=/; Secure; SameSite=Lax`. Only values that are safe to show to any script may skip HttpOnly.');
