INSERT INTO challenge.challenge_test_cases (challenge_id, name, input_data, expected_output, score, is_sample, is_hidden, sort_order)
VALUES ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_422'), 'Login works: the SPA greets the learner, GET /me and refresh succeed', '{"sessions":[{"user":{"id":"u_17","displayName":"Lan Nguyen"},"tokens":{"accessToken":"at_VEfHBE0V2CVZe_KHqC_28mTf9yeu4jshRFwhxCPBU1M","refreshToken":"rt_-oHj2Y-OLXDGcwxEj_IZ5dYRjlSQX8KshHEczsr_FhE"}}],"probes":["me","refresh"]}', '"u_17 login: 200, SPA shows \"Hi, Lan Nguyen\"\nu_17 GET /me: 200\nu_17 POST /auth/refresh: 200"', 3, true, false, 1),
       ((SELECT id FROM challenge.challenges WHERE public_id = 'chal_coding_nas_422'), 'Two learners with Vietnamese names sign in, call the API and refresh', '{"sessions":[{"user":{"id":"u_204","displayName":"Lê Thu Hà"},"tokens":{"accessToken":"at_jy1QS_HSOFx1FXqWylASBZ8ja85QjorAfb2ZOYG5MVc","refreshToken":"rt_x1XrrDhv0C1008HVuUNSErGtW8Mwlgv6WzHjq_qNlqc"}},{"user":{"id":"u_318","displayName":"Trần Minh Đức"},"tokens":{"accessToken":"at_tv8X61Domhe4Wpdukdm2wPngq3lQUTIJTE5FjxGkxaY","refreshToken":"rt_dniT97DvIrtAebUIijKZYL-h0kc3zPYqCxCOCqWMA3o"}}],"probes":["me","refresh","me"]}', '"u_204 login: 200, SPA shows \"Hi, Lê Thu Hà\"\nu_204 GET /me: 200\nu_204 POST /auth/refresh: 200\nu_204 GET /me: 200\nu_318 login: 200, SPA shows \"Hi, Trần Minh Đức\"\nu_318 GET /me: 200\nu_318 POST /auth/refresh: 200\nu_318 GET /me: 200"', 3, true, false, 2),
