WHERE NOT EXISTS (SELECT 1 FROM course.lesson WHERE content_source = 'lesson-nas-4-3' AND is_deleted = false);

-- challenge chal_quiz_nas_431 (quiz)
INSERT INTO challenge.challenges (public_id, course_id, module_id, lesson_id, name, title, description, status, difficulty, type, points, is_published, is_deleted)
VALUES ('chal_quiz_nas_431', (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security'), (SELECT id FROM course.module WHERE course_id = (SELECT id FROM catalog.course WHERE public_id = 'nodejs-api-security') AND order_index = 4 AND is_deleted = false LIMIT 1), (SELECT id FROM course.lesson WHERE content_source = 'lesson-nas-4-3' AND is_deleted = false LIMIT 1), 'sign-in-threat-review-quiz', 'Read the threat review evidence', 'Three findings from the threat review of CodeDev''s sign-in flow: a log redaction list, a weekend of failed logins against the current rate limits, and the password reset handler.', 'open', 'medium'::difficulty_question, 'quiz', 10, true, false)
ON CONFLICT (public_id) DO UPDATE SET
    course_id = EXCLUDED.course_id, module_id = EXCLUDED.module_id, lesson_id = EXCLUDED.lesson_id, name = EXCLUDED.name,
    title = EXCLUDED.title, description = EXCLUDED.description, difficulty = EXCLUDED.difficulty, type = EXCLUDED.type,
    points = EXCLUDED.points, is_published = true, is_deleted = false, updated_at = now();
DELETE FROM challenge.challenge_hints WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431');
UPDATE challenge.challenges SET quiz_display_count = NULL WHERE id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431');
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431'), 'Logger of the API:

const logger = pino({ redact: ["req.headers.authorization"] });
app.use(pinoHttp({ logger }));

One line from yesterday''s log (shortened):

{"req":{"method":"POST","url":"/auth/refresh","headers":{"host":"api.codedev.test","authorization":"[Redacted]","cookie":"__Secure-cd_rt=rt_9fKq2...; display_name=Lan%20Nguyen"}},"res":{"statusCode":200},"responseTime":41}

Statement: "With this redact list, refresh tokens cannot end up in the API''s logs."', 'single_choice'::question_type, 'False. The redact list covers only the Authorization header, but since lesson 4.2 the tokens travel in cookies, and pino-http logs req.headers.cookie in full: the line above contains a working refresh token. Responses can leak too through the Set-Cookie header of /auth/login and /auth/refresh. The list needs req.headers.cookie and res.headers["set-cookie"] (or a serializer that logs only an allowlist of headers), plus a test that greps a captured log for the token. The misconception is that redacting Authorization covers tokens wherever they are sent.', 1, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431') AND order_index = 1)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', false),
        ('False', true)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431'), 'Current limits on POST /auth/login: at most 20 failed logins per IP and at most 10 failed logins per account, each per 15 minutes. Saturday 02:00-05:00, from the auth_events table:

failed logins             41,200   (normal night: about 900)
successful logins             37   from IPs never seen for those accounts
distinct source IPs        3,912
max failures per IP / 15 min    6
max failures per account        2
distinct emails tried      39,850   (most are not CodeDev accounts)

Statement: "This traffic never reached either limit, so the limits did not slow it down; a signal across all logins, such as the global failure rate or successful logins from new devices, is what shows this attack."', 'single_choice'::question_type, 'True. This is credential stuffing: email and password pairs leaked from other sites, spread over thousands of IPs so that each IP stays at 6 failures and each account at 1 or 2. Per-IP and per-account limits are still worth having against simple brute force, but they cannot see an attack designed to stay under them. What stands out is the shape of all traffic together: failures at about 45 times the normal level, most emails unknown, and 37 successes from new devices. Alerts on those, plus a breached-password check and MFA, are the defences that fit. The misconception is that a per-IP limit stops any login attack.', 2, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431') AND order_index = 2)
    RETURNING id
)
INSERT INTO challenge.question_options (question_id, option_text, is_correct)
SELECT q.id, o.option_text, o.is_correct
FROM q, (VALUES
        ('True', true),
        ('False', false)
    ) AS o(option_text, is_correct);
WITH q AS (
    INSERT INTO challenge.questions (challenge_id, question, type, explanation, order_index, points)
    SELECT (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431'), 'Password reset, as it is today:

async resetPassword(token: string, newPassword: string) {
  const row = await db.one("SELECT user_id FROM password_resets WHERE token = $1 AND created_at > now() - interval ''24 hours''", [token]);
  await db.query("UPDATE users SET password_hash = $1 WHERE id = $2", [await argon2.hash(newPassword), row.user_id]);
}

Access tokens live 15 minutes, refresh tokens 14 days with rotation and replay detection. Last week an attacker copied a learner''s refresh token from her shared computer; she has not used that computer since.

Statement: "Once the learner resets her password with this handler, the attacker loses access within 15 minutes, when the last access token expires."', 'single_choice'::question_type, 'False. The handler only replaces the password hash. It does not revoke the refresh token families or bump the session version (lesson 4.1), so the attacker''s refresh token keeps rotating for up to 14 days, each time getting a fresh access token; replay detection does not fire because the learner never uses that token again. The handler has more problems a threat review should list: the reset token is stored and compared in plain text, it is never marked as used, and 24 hours is a long window. The misconception is that changing the password ends existing sessions by itself.', 3, 5
    WHERE NOT EXISTS (SELECT 1 FROM challenge.questions WHERE challenge_id = (SELECT id FROM challenge.challenges WHERE public_id = 'chal_quiz_nas_431') AND order_index = 3)
    RETURNING id
)
